mapper.select:
select

from address_standard_import_fail_detail d
left join address_standard_import_record b on b.id = d.batch_id and coalesce(b.del_flag, '0') = '0'

    coalesce(d.del_flag, '0') = '0'

        and d.batch_id = #{bo.batchId}



        and b.file_name like #{fileNameLike}



            and d.status = 'WAITING_APPROVAL'


            and d.status = 'APPROVED_SUCCESS'


            and d.status in ('VALIDATE_FAILED', 'REJECTED_FAILED', 'EXECUTE_FAILED')


            and d.status = #{bo.status}




        and d.segm_name like #{segmNameLike}


        and d.create_by = #{bo.createBy}


        and d.create_time between #{bo.params.beginTime} and #{bo.params.endTime}


order by d.create_time desc, d.id desc
